(6878169, 1035576, 30214, '<td valign="top">pretty good finish Paul, so there is some justice around here :)</td>', 'pretty good finish Paul, so there is some justice around here :)', '2012-10-08 01:41:29.000000', NULL, 0),
(6878178, 1035831, 63503, '<td valign="top">This may not be a portrait but it is a most powerful picture with a touching story and fitting title. This picture is a clear example of how art overpowers any technical shortcoming. Congratulations on such a great photograph Claudia. You knew it is not the kind of photo that scores high in DPC, but that does not matter because I am sure it will be appreciated by those who look for artistic value.<br/> <br/>ETA: Congratulations on the posthumous award too !!!<br/><br/><i>Message edited by author 2012-10-08 01:03:50.</i></td>', 'This may not be a portrait but it is a most powerful picture with a touching story and fitting title. This picture is a clear example of how art overpowers any technical shortcoming. Congratulations on such a great photograph Claudia. You knew it is not the kind of photo that scores high in DPC, but that does not matter because I am sure it will be appreciated by those who look for artistic value. ETA: Congratulations on the posthumous award too !!!', '2012-10-08 01:51:24.000000', '2012-10-08 02:03:50.000000', 0),
(6878184, 1035569, 62357, '<td valign="top">Congratulations on the ribbon Urfa.  I love this.</td>', 'Congratulations on the ribbon Urfa.  I love this.', '2012-10-08 02:09:22.000000', NULL, 0),
(6878185, 1035576, 62357, '<td valign="top">Not surprised to find this was yours Paul.  Great stuff.</td>', 'Not surprised to find this was yours Paul.  Great stuff.', '2012-10-08 02:10:24.000000', NULL, 0),
(6878190, 1034986, 28742, '<td valign="top">Wow Lydia - VERY nicely done. I gave her/you a 9. Congrats!<br/>eta: THREE CHEERS FOR DOGS &amp; WINE! :) <br/><br/><i>Message edited by author 2012-10-08 01:15:15.</i></td>', 'Wow Lydia - VERY nicely done. I gave her/you a 9. Congrats!eta: THREE CHEERS FOR DOGS & WINE! :) ', '2012-10-08 02:12:33.000000', '2012-10-08 02:15:15.000000', 0),
(6878191, 1035780, 62357, '<td valign="top">Wonderful Lev.  One of my highest scoring in this challenge.</td>', 'Wonderful Lev.  One of my highest scoring in this challenge.', '2012-10-08 02:16:04.000000', NULL, 0),
(6878193, 1035765, 16106, '<td valign="top">I deeply love this image.The isolation if an individual in a crowd. The archetype of the cheerleader shifted to a unique individual whom you can not dismiss as an archetype. Great capture.</td>', 'I deeply love this image.The isolation if an individual in a crowd. The archetype of the cheerleader shifted to a unique individual whom you can not dismiss as an archetype. Great capture.', '2012-10-08 02:19:07.000000', NULL, 0),
(6878195, 1035831, 28742, '<td valign="top">Way to go on the PH award, Claudia. This is a beautiful image.</td>', 'Way to go on the PH award, Claudia. This is a beautiful image.', '2012-10-08 02:20:53.000000', NULL, 0),
(6878196, 1035513, 28742, '<td valign="top">Beautifully haunting. A shock to see it languishing down in the low 5''s. I gave it a 7. Congrats on the PH - well deserved.</td>', 'Beautifully haunting. A shock to see it languishing down in the low 5''s. I gave it a 7. Congrats on the PH - well deserved.', '2012-10-08 02:22:57.000000', NULL, 0),
